package com.agacostays.payroll.security;
import io.jsonwebtoken.*; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.util.StringUtils; import org.springframework.web.filter.OncePerRequestFilter; import javax.crypto.spec.SecretKeySpec; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.util.List;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter{
 private final String secret,issuer; public JwtAuthenticationFilter(@Value("${security.jwt.secret}")String s,@Value("${security.jwt.issuer}")String i){secret=s;issuer=i;}
 protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{
  String h=r.getHeader("Authorization"); if(StringUtils.hasText(h)&&h.startsWith("Bearer ")){try{var k=new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256");Claims cl=Jwts.parser().verifyWith(k).requireIssuer(issuer).build().parseSignedClaims(h.substring(7)).getPayload();Long id=cl.get("userId",Long.class);String role=cl.get("role",String.class);if(role==null)role=cl.get("roles",String.class);if(role!=null){var a=new UsernamePasswordAuthenticationToken(id==null?cl.getSubject():String.valueOf(id),null,List.of(new SimpleGrantedAuthority("ROLE_"+role.replace("ROLE_",""))));SecurityContextHolder.getContext().setAuthentication(a);}}catch(Exception ignored){}} c.doFilter(r,s);
 }
}
